// DejaVu Sans subsets: Latin, Greek, Cyrillic and document punctuation.
// License: docs/licenses/DejaVu.txt. Embedded to avoid viewer-dependent substitutions.
import type { jsPDF } from "jspdf";
const regular = "";
const bold = "";
export function registerPdfFonts(doc: jsPDF) {
 doc.addFileToVFS("LtcSans.ttf", regular);
 doc.addFileToVFS("LtcSans-Bold.ttf", bold);
 doc.addFont("LtcSans.ttf", "helvetica", "normal");
 doc.addFont("LtcSans.ttf", "helvetica", "italic");
 doc.addFont("LtcSans-Bold.ttf", "helvetica", "bold");
 doc.addFont("LtcSans-Bold.ttf", "helvetica", "bolditalic");
 doc.setFont("helvetica", "normal");
}
